from __future__ import print_function
import sys
import os
import argparse
from io import open

parser = argparse.ArgumentParser()
parser.add_argument('statuscodes', help='path/to/Opc.Ua.NodeIds.csv')
parser.add_argument('outfile', help='outfile w/o extension')
parser.add_argument('namespace', help='NS0')
args = parser.parse_args()

rows = []
with open(args.statuscodes, mode="rt") as f:
    lines = f.readlines()
    for l in lines:
        rows.append(tuple(l.strip().split(',')))

fh = open(args.outfile + ".inc", "wt", encoding='utf8')
def printh(string):
    print(string, end=u'\n', file=fh)

#########################
# Print the header file #
#########################

printh(u'''(*---------------------------------------------------------
 * Autogenerated -- do not modify
 * Generated from {0} with script {1}
 *-------------------------------------------------------*)


(**
 * Namespace Zero NodeIds
 * ----------------------
 * Numeric identifiers of standard-defined nodes in namespace zero. The
 * following definitions are autogenerated from the ``{0}`` file *)
'''.format(os.path.basename(args.statuscodes), os.path.basename(sys.argv[0]), args.namespace))

# Free Pascal identifiers are significant up to 127 characters only: longer
# names (open62541 >= 1.4 has some) keep their start and end with "_<id>",
# which keeps them unique.
MAXIDENT = 127
seen = set()
for row in rows:
    if len(row) < 2:
        continue
    name = u"UA_{0}ID_{1}".format(args.namespace, row[0].upper())
    if len(name) > MAXIDENT:
        suffix = u"_" + row[1]
        name = name[:MAXIDENT - len(suffix)] + suffix
    if name in seen:
        continue
    seen.add(name)
    printh(u"{name} = {id}; (* {description} *)".format(name=name, id=row[1], description=(row[2] if len(row) > 2 else u'').replace(u'*)', u'* )')))

fh.close()
